#!/usr/bin/env python3
"""Validator for synthetic heldout web source sets generated by gen_heldout.py.

Usage:
    python3 check_heldout.py <dir>
"""

from __future__ import annotations

import hashlib
import json
import re
import sys
from collections import Counter
from pathlib import Path

EXPECTED_SCHEMA = "vacant.d2.manifest/1"
EXPECTED_GENERATOR = "heldout-v1"
ALLOWED_EXTS = {".html", ".md", ".txt"}
FORBIDDEN_P_NAME_RE = re.compile(r"^p\d+", re.IGNORECASE)

VALUE_TOKEN_RE = re.compile(
    r"(?<![A-Za-z0-9.])v\d+\.\d+(?:\.\d+)?(?![A-Za-z0-9.])"
    r"|(?<![A-Za-z0-9.,])\d{1,3}(?:,\d{3})+(?:\.\d+)?(?![A-Za-z0-9.,])"
    r"|(?<![A-Za-z0-9.,])\d+(?:\.\d+)?(?![A-Za-z0-9.,])"
)


def extract_single_token(value: str) -> tuple[str | None, str | None]:
    """Validate that value contains exactly one number or version string and no stray digits."""
    if not isinstance(value, str) or not value.strip():
        return None, "value must be a non-empty string"
    matches = list(VALUE_TOKEN_RE.finditer(value))
    if len(matches) != 1:
        return None, f"expected exactly 1 number/version token in {value!r}, found {len(matches)}"
    m = matches[0]
    remainder = value[: m.start()] + value[m.end() :]
    if re.search(r"\d", remainder):
        return None, f"unexpected extra digits in {value!r}"
    return m.group(0), None


def token_key(token: str) -> tuple:
    if token.startswith("v"):
        return ("v",) + tuple(int(p) for p in token[1:].split("."))
    return ("n", round(float(token.replace(",", "")), 6))


def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def validate_directory(out_dir: Path) -> list[str]:
    errors: list[str] = []

    def err(msg: str) -> None:
        errors.append(msg)

    if not out_dir.is_dir():
        return [f"Target directory does not exist or is not a directory: {out_dir}"]

    manifest_path = out_dir / "manifest.json"
    sha_path = out_dir / "manifest.sha256"

    if not manifest_path.is_file():
        return [f"Missing manifest.json at {manifest_path}"]
    if not sha_path.is_file():
        err(f"Missing manifest.sha256 at {sha_path}")

    manifest_bytes = manifest_path.read_bytes()
    actual_manifest_sha = sha256_bytes(manifest_bytes)

    if sha_path.is_file():
        raw_sha = sha_path.read_text(encoding="utf-8").strip()
        parts = raw_sha.split()
        if len(parts) == 1:
            recorded_sha = parts[0]
        elif len(parts) == 2 and parts[1] == "manifest.json":
            recorded_sha = parts[0]
        else:
            recorded_sha = ""
            err(f"Invalid manifest.sha256 format: {raw_sha!r}")
        if recorded_sha and recorded_sha != actual_manifest_sha:
            err(
                f"manifest.sha256 mismatch: recorded={recorded_sha}, actual={actual_manifest_sha}"
            )

    try:
        manifest = json.loads(manifest_bytes.decode("utf-8"))
    except Exception as exc:
        return errors + [f"Failed to parse manifest.json: {exc}"]

    if not isinstance(manifest, dict):
        return errors + ["manifest.json root must be an object"]

    if manifest.get("schema") != EXPECTED_SCHEMA:
        err(f"schema mismatch: got {manifest.get('schema')!r}, expected {EXPECTED_SCHEMA!r}")
    if manifest.get("generator") != EXPECTED_GENERATOR:
        err(f"generator mismatch: got {manifest.get('generator')!r}, expected {EXPECTED_GENERATOR!r}")
    if not isinstance(manifest.get("seed"), int) or isinstance(manifest.get("seed"), bool):
        err(f"seed must be an integer, got {manifest.get('seed')!r}")

    n_sets = manifest.get("n_sets")
    sets_list = manifest.get("sets")
    if not isinstance(n_sets, int) or isinstance(n_sets, bool) or n_sets < 1:
        err(f"n_sets must be a positive integer, got {n_sets!r}")
    if not isinstance(sets_list, list):
        return errors + ["manifest.sets must be a list"]
    if isinstance(n_sets, int) and len(sets_list) != n_sets:
        err(f"len(sets)={len(sets_list)} does not match n_sets={n_sets}")

    cycle_types = manifest.get("cycle_types")
    if not isinstance(cycle_types, list) or Counter(cycle_types) != Counter(["F", "F", "N", "Z"]):
        err(f"top-level cycle_types must have multiset {{F,F,N,Z}}, got {cycle_types!r}")

    sets_root = out_dir / "sets"
    if not sets_root.is_dir():
        err(f"Missing sets directory at {sets_root}")
    else:
        expected_set_ids = [f"s{i + 1:02d}" for i in range(len(sets_list))]
        actual_set_dirs = sorted(p.name for p in sets_root.iterdir() if p.is_dir())
        if actual_set_dirs != sorted(expected_set_ids):
            err(
                f"sets/ subdirectories {actual_set_dirs} do not match expected {sorted(expected_set_ids)}"
            )

    for idx, s in enumerate(sets_list):
        expected_sid = f"s{idx + 1:02d}"
        sid = s.get("set")
        prefix = f"[{sid or expected_sid}]"
        if sid != expected_sid:
            err(f"{prefix} set id mismatch: expected {expected_sid!r}, got {sid!r}")

        domain = s.get("domain")
        if not isinstance(domain, str) or not domain.strip():
            err(f"{prefix} missing or empty domain")

        index_fn = s.get("index")
        pages = s.get("pages")
        if not isinstance(index_fn, str) or not index_fn:
            err(f"{prefix} invalid index filename: {index_fn!r}")
            continue
        if not isinstance(pages, list) or not all(isinstance(p, str) for p in pages):
            err(f"{prefix} invalid pages list")
            continue

        if not (5 <= len(pages) <= 7):
            err(f"{prefix} expected 5..7 content pages, got {len(pages)}")
        if len(set(pages)) != len(pages):
            err(f"{prefix} duplicate filenames in pages")
        if index_fn in pages:
            err(f"{prefix} index {index_fn!r} must not appear in pages list")

        all_files = [index_fn] + pages
        for fn in all_files:
            if "/" in fn or "\\" in fn or Path(fn).name != fn:
                err(f"{prefix} filename {fn!r} must be a bare relative filename")
            ext = Path(fn).suffix.lower()
            if ext not in ALLOWED_EXTS:
                err(f"{prefix} filename {fn!r} has unsupported extension {ext!r}")
            stem = Path(fn).stem
            if FORBIDDEN_P_NAME_RE.match(stem):
                err(f"{prefix} filename {fn!r} violates descriptive slug rule (looks like p<digit>)")

        all_fmts = {Path(fn).suffix.lower() for fn in all_files}
        page_fmts = {Path(fn).suffix.lower() for fn in pages}
        if len(all_fmts) < 2:
            err(f"{prefix} set must use at least 2 formats, found {sorted(all_fmts)}")
        if len(page_fmts) < 2:
            err(f"{prefix} content pages should use at least 2 formats, found {sorted(page_fmts)}")

        # Claims validation
        claims = s.get("claims")
        if not isinstance(claims, list) or len(claims) != 20:
            err(f"{prefix} expected exactly 20 claims, got {len(claims) if isinstance(claims, list) else type(claims).__name__}")
            continue

        expected_cids = [f"c{i + 1:02d}" for i in range(20)]
        claim_map: dict[str, dict] = {}
        entities_seen: set[str] = set()
        template_lines_seen: list[str] = []
        multi_page_count = 0

        for c_idx, c in enumerate(claims):
            cid = c.get("id")
            if cid != expected_cids[c_idx]:
                err(f"{prefix} claim #{c_idx + 1} id mismatch: expected {expected_cids[c_idx]!r}, got {cid!r}")
            ent = c.get("entity")
            label = c.get("label")
            tline = c.get("template_line")
            spages = c.get("source_pages")
            if not isinstance(ent, str) or not ent.strip():
                err(f"{prefix} {cid} invalid entity: {ent!r}")
                continue
            if not isinstance(label, str) or not label.strip():
                err(f"{prefix} {cid} invalid label: {label!r}")
                continue
            entities_seen.add(ent)
            expected_tline = f"- {ent} \u2014 {label}: "
            if tline != expected_tline:
                err(f"{prefix} {cid} template_line mismatch: got {tline!r}, expected {expected_tline!r}")
            template_lines_seen.append(tline)

            if not isinstance(spages, list) or not (1 <= len(spages) <= 3):
                err(f"{prefix} {cid} source_pages must contain 1..3 pages, got {spages!r}")
            else:
                if len(set(spages)) != len(spages):
                    err(f"{prefix} {cid} duplicate entries in source_pages: {spages!r}")
                for sp in spages:
                    if sp not in pages:
                        err(f"{prefix} {cid} source_page {sp!r} is not in content pages")
                if len(spages) >= 2:
                    multi_page_count += 1
            claim_map[cid] = c

        if not (4 <= len(entities_seen) <= 6):
            err(f"{prefix} expected 4..6 entities, found {len(entities_seen)}: {sorted(entities_seen)}")
        if len(set(template_lines_seen)) != 20:
            err(f"{prefix} template_line prefixes are not unique within set")
        if multi_page_count == 0:
            err(f"{prefix} expected ~30% multi-page claims (2-3 pages), found 0")

        # Validate template.md
        set_dir = sets_root / expected_sid
        tpl_path = set_dir / "template.md"
        if not tpl_path.is_file():
            err(f"{prefix} missing template.md at {tpl_path}")
        else:
            tpl_lines = [ln.rstrip("\r") for ln in tpl_path.read_text(encoding="utf-8").splitlines()]
            non_empty = [ln for ln in tpl_lines if ln.strip()]
            if len(non_empty) < 22:
                err(f"{prefix} template.md too short ({len(non_empty)} non-empty lines)")
            else:
                if not non_empty[0].startswith("# "):
                    err(f"{prefix} template.md first line must be a '# ' title, got {non_empty[0]!r}")
                if non_empty[1].startswith("#") or non_empty[1].startswith("- "):
                    err(f"{prefix} template.md second non-empty line must be an instruction line, got {non_empty[1]!r}")
                body_lines = non_empty[2:]
                claim_lines_in_tpl: list[str] = []
                for ln in body_lines:
                    if ln.startswith("## "):
                        continue
                    if ln.startswith("- ") and ln.endswith(": ____"):
                        claim_lines_in_tpl.append(ln[: -len("____")])
                    else:
                        err(f"{prefix} template.md unexpected line format: {ln!r}")
                if len(claim_lines_in_tpl) != 20:
                    err(f"{prefix} template.md expected 20 claim lines, found {len(claim_lines_in_tpl)}")
                if len(set(claim_lines_in_tpl)) != len(claim_lines_in_tpl):
                    err(f"{prefix} duplicate claim lines in template.md")
                if set(claim_lines_in_tpl) != set(template_lines_seen):
                    missing = set(template_lines_seen) - set(claim_lines_in_tpl)
                    extra = set(claim_lines_in_tpl) - set(template_lines_seen)
                    err(f"{prefix} template.md claim lines mismatch manifest (missing={missing}, extra={extra})")

        # Validate truth (5 entries: cycle 0..4)
        truth = s.get("truth")
        if not isinstance(truth, list) or len(truth) != 5:
            err(f"{prefix} expected 5 truth entries (cycles 0..4), got {len(truth) if isinstance(truth, list) else type(truth).__name__}")
            continue

        for cyc_idx, tdict in enumerate(truth):
            if not isinstance(tdict, dict) or set(tdict.keys()) != set(expected_cids):
                err(f"{prefix} cycle_{cyc_idx} truth keys do not match c01..c20")
                continue
            for cid, val in tdict.items():
                _tok, tok_err = extract_single_token(val)
                if tok_err:
                    err(f"{prefix} cycle_{cyc_idx} {cid}: {tok_err}")

        # Validate page_sha256 & actual files on disk for cycles 0..4
        page_sha256 = s.get("page_sha256")
        if not isinstance(page_sha256, list) or len(page_sha256) != 5:
            err(f"{prefix} expected 5 page_sha256 entries, got {len(page_sha256) if isinstance(page_sha256, list) else type(page_sha256).__name__}")
            continue

        cycle_file_bytes: list[dict[str, bytes]] = []
        for cyc_idx in range(5):
            site_dir = set_dir / f"cycle_{cyc_idx}" / "site"
            if not site_dir.is_dir():
                err(f"{prefix} missing site directory {site_dir}")
                cycle_file_bytes.append({})
                continue

            disk_files = sorted(p.name for p in site_dir.iterdir() if p.is_file())
            expected_files = sorted(all_files)
            if disk_files != expected_files:
                err(f"{prefix} cycle_{cyc_idx} files on disk {disk_files} != expected {expected_files}")

            sha_map = page_sha256[cyc_idx]
            if not isinstance(sha_map, dict) or set(sha_map.keys()) != set(expected_files):
                err(f"{prefix} cycle_{cyc_idx} page_sha256 keys do not match site files")

            bytes_map: dict[str, bytes] = {}
            text_map: dict[str, str] = {}
            for fn in disk_files:
                raw = (site_dir / fn).read_bytes()
                bytes_map[fn] = raw
                text_map[fn] = raw.decode("utf-8")
                actual_h = sha256_bytes(raw)
                if isinstance(sha_map, dict) and sha_map.get(fn) != actual_h:
                    err(
                        f"{prefix} cycle_{cyc_idx} sha256 mismatch for {fn}: "
                        f"recorded={sha_map.get(fn)}, actual={actual_h}"
                    )

            cycle_file_bytes.append(bytes_map)

            # Check index links to every content page
            if index_fn in text_map:
                idx_txt = text_map[index_fn]
                for pfn in pages:
                    if pfn not in idx_txt:
                        err(f"{prefix} cycle_{cyc_idx} index {index_fn} missing relative link to {pfn}")

            # Check narrative / non-table / <= 1 list per content page
            for pfn in pages:
                if pfn not in text_map:
                    continue
                ptxt = text_map[pfn]
                ext = Path(pfn).suffix.lower()
                if ext == ".html":
                    if "<table" in ptxt.lower():
                        err(f"{prefix} cycle_{cyc_idx} {pfn} contains an HTML <table>")
                    if len(re.findall(r"<ul\b", ptxt, re.IGNORECASE)) > 1:
                        err(f"{prefix} cycle_{cyc_idx} {pfn} contains more than one <ul> list")
                elif ext == ".md":
                    if re.search(r"^\s*\|.*\|\s*$\n\s*\|[\s:-]+\|\s*$", ptxt, re.MULTILINE):
                        err(f"{prefix} cycle_{cyc_idx} {pfn} contains a Markdown table")

            # Check verbatim truth presence on every source_page
            tdict = truth[cyc_idx]
            if isinstance(tdict, dict):
                for cid, cobj in claim_map.items():
                    val = tdict.get(cid)
                    if not isinstance(val, str):
                        continue
                    for sp in cobj.get("source_pages", []):
                        if sp in text_map and val not in text_map[sp]:
                            err(
                                f"{prefix} cycle_{cyc_idx} {cid} value {val!r} not found verbatim on {sp}"
                            )

        # Validate cycles 1..4 transitions
        cycles = s.get("cycles")
        if not isinstance(cycles, list) or len(cycles) != 4:
            err(f"{prefix} expected 4 cycle entries, got {len(cycles) if isinstance(cycles, list) else type(cycles).__name__}")
            continue

        seen_types: list[str] = []
        ever_changed_claims: set[str] = set()

        for c_i, cyc in enumerate(cycles, start=1):
            if cyc.get("cycle") != c_i:
                err(f"{prefix} cycles[{c_i - 1}].cycle expected {c_i}, got {cyc.get('cycle')!r}")
            ctype = cyc.get("type")
            seen_types.append(ctype)
            rec_changed = cyc.get("changed_claims")
            rec_noise = cyc.get("noise_pages")

            if not isinstance(rec_changed, list) or len(set(rec_changed)) != len(rec_changed):
                err(f"{prefix} cycle {c_i} invalid changed_claims: {rec_changed!r}")
                continue
            if not isinstance(rec_noise, list) or len(set(rec_noise)) != len(rec_noise):
                err(f"{prefix} cycle {c_i} invalid noise_pages: {rec_noise!r}")
                continue

            prev_t = truth[c_i - 1]
            cur_t = truth[c_i]
            actual_changed = sorted(cid for cid in expected_cids if cur_t.get(cid) != prev_t.get(cid))

            if sorted(rec_changed) != actual_changed:
                err(
                    f"{prefix} cycle {c_i} changed_claims {rec_changed} != actual truth diff {actual_changed}"
                )

            # Check each changed claim differs in its number/version and changes at most once overall
            for cid in actual_changed:
                if cid in ever_changed_claims:
                    err(f"{prefix} cycle {c_i} claim {cid} changed more than once across cycles")
                ever_changed_claims.add(cid)
                tok_old, err_old = extract_single_token(prev_t[cid])
                tok_new, err_new = extract_single_token(cur_t[cid])
                if not err_old and not err_new and tok_old and tok_new:
                    if token_key(tok_old) == token_key(tok_new):
                        err(
                            f"{prefix} cycle {c_i} claim {cid} new value {cur_t[cid]!r} "
                            f"does not differ in number/version from {prev_t[cid]!r}"
                        )

            # File byte diffs between cycle c_i - 1 and cycle c_i
            prev_bytes = cycle_file_bytes[c_i - 1]
            cur_bytes = cycle_file_bytes[c_i]
            changed_files = {
                fn for fn in set(prev_bytes) | set(cur_bytes)
                if prev_bytes.get(fn) != cur_bytes.get(fn)
            }

            for np in rec_noise:
                if np not in all_files:
                    err(f"{prefix} cycle {c_i} noise_page {np!r} is not a valid site file")

            if ctype == "Z":
                if actual_changed:
                    err(f"{prefix} cycle {c_i} (Z) must not change any truth values, changed {actual_changed}")
                if rec_noise:
                    err(f"{prefix} cycle {c_i} (Z) must have empty noise_pages, got {rec_noise}")
                if changed_files:
                    err(f"{prefix} cycle {c_i} (Z) must be byte-identical to previous cycle, changed {sorted(changed_files)}")
            elif ctype == "N":
                if actual_changed:
                    err(f"{prefix} cycle {c_i} (N) must not change any truth values, changed {actual_changed}")
                if not (1 <= len(rec_noise) <= 2):
                    err(f"{prefix} cycle {c_i} (N) expected 1..2 noise_pages, got {rec_noise}")
                if changed_files != set(rec_noise):
                    err(
                        f"{prefix} cycle {c_i} (N) changed files {sorted(changed_files)} "
                        f"!= noise_pages {sorted(rec_noise)}"
                    )
            elif ctype == "F":
                if len(actual_changed) != 2:
                    err(f"{prefix} cycle {c_i} (F) expected 2 changed claims, got {actual_changed}")
                if len(rec_noise) != 1:
                    err(f"{prefix} cycle {c_i} (F) expected 1 noise_page, got {rec_noise}")
                affected_claim_pages: set[str] = set()
                for cid in actual_changed:
                    affected_claim_pages.update(claim_map[cid]["source_pages"])
                expected_changed_files = affected_claim_pages | set(rec_noise)
                if changed_files != expected_changed_files:
                    err(
                        f"{prefix} cycle {c_i} (F) changed files {sorted(changed_files)} "
                        f"!= expected {sorted(expected_changed_files)}"
                    )
            else:
                err(f"{prefix} cycle {c_i} unknown cycle type {ctype!r}")

        if Counter(seen_types) != Counter(["F", "F", "N", "Z"]):
            err(f"{prefix} cycle types {seen_types} do not match multiset {{F,F,N,Z}}")

    return errors


def main(argv: list[str] | None = None) -> int:
    args = sys.argv[1:] if argv is None else argv
    if len(args) != 1 or args[0] in {"-h", "--help"}:
        print("Usage: python3 check_heldout.py <dir>", file=sys.stderr)
        return 2
    target = Path(args[0])
    errors = validate_directory(target)
    if errors:
        print(f"FAIL: {len(errors)} validation error(s) in {target}:", file=sys.stderr)
        for e in errors:
            print(f"  - {e}", file=sys.stderr)
        return 1

    manifest = json.loads((target / "manifest.json").read_text(encoding="utf-8"))
    print(
        f"OK: {target} passed all checks "
        f"(seed={manifest['seed']}, sets={manifest['n_sets']}, schema={manifest['schema']})"
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
